#!/bin/bash
# Prints the Homebrew formula for a release.
#   packaging/homebrew-formula.sh <tag> <dir with the release .tar.gz files>
set -euo pipefail
tag="$1"
dir="$2"
version="${tag#v}"
base="https://github.com/sadayamuthu/mergelock/releases/download/${tag}"

sha() { shasum -a 256 "${dir}/mergelock_${tag}_$1.tar.gz" | cut -d' ' -f1; }

cat <<EOF
# Generated by packaging/homebrew-formula.sh in sadayamuthu/mergelock; edits here are overwritten.
class Mergelock < Formula
  desc "Find merge conflicts git can't see between branches"
  homepage "https://github.com/sadayamuthu/mergelock"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "${base}/mergelock_${tag}_darwin_arm64.tar.gz"
      sha256 "$(sha darwin_arm64)"
    end
    on_intel do
      url "${base}/mergelock_${tag}_darwin_amd64.tar.gz"
      sha256 "$(sha darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "${base}/mergelock_${tag}_linux_arm64.tar.gz"
      sha256 "$(sha linux_arm64)"
    end
    on_intel do
      url "${base}/mergelock_${tag}_linux_amd64.tar.gz"
      sha256 "$(sha linux_amd64)"
    end
  end

  def install
    bin.install "mergelock"
  end

  test do
    assert_match "mergelock v#{version}", shell_output("#{bin}/mergelock version")
  end
end
EOF
